// @name Archive films
// Old films from the Internet Archive (archive.org), free to watch: feature
// films, the Prelinger Archives' ephemeral films, cartoons, silent films,
// film noir, classic TV. One at a time from the collection's most watched,
// its title and year at the start, the next one when it ends; a tap moves on.
// Plays on a Raspberry Pi (docs/video.md); no account or key needed.
const SEARCH = 'https://archive.org/advancedsearch.php'
const POPULAR_PAGES = 20 // of 50: a film from the collection's 1,000 most downloaded
const FORMATS = ['h.264', 'MPEG4', 'h.264 IA', '512Kb MPEG4']
const TITLE_MS = 7000
const RETRY_MS = 60000

let current = null // { id, title, year, url }
let startedAt = 0
let problem = ''
let problemAt = 0
let collection = ''
let tries = 0

function fetchJson(url) {
  const r = frameos.httpRequest(url, { timeoutMs: 30000, headers: { Accept: 'application/json' } })
  if (r.status !== 200) throw new Error(r.status ? `archive.org answered HTTP ${r.status}` : `archive.org did not answer: ${r.error ?? ''}`)
  return JSON.parse(r.body ?? 'null')
}

function pickFilm(name) {
  const q = encodeURIComponent(`collection:(${name}) AND mediatype:(movies)`)
  const page = 1 + Math.floor(Math.random() * POPULAR_PAGES)
  const found = fetchJson(`${SEARCH}?q=${q}&fl%5B%5D=identifier&fl%5B%5D=title&fl%5B%5D=year&sort%5B%5D=downloads+desc&rows=50&page=${page}&output=json`)
  const docs = found?.response?.docs ?? []
  if (!docs.length) throw new Error(`Nothing found in the collection “${name}”.`)
  const doc = docs[Math.floor(Math.random() * docs.length)]
  const id = String(doc.identifier)
  // Its files: the first video in a format a Pi plays well.
  const meta = fetchJson(`https://archive.org/metadata/${encodeURIComponent(id)}`)
  const files = Array.isArray(meta?.files) ? meta.files : []
  let file = null
  for (const format of FORMATS) {
    file = files.find((f) => f?.format === format && typeof f.name === 'string')
    if (file) break
  }
  if (!file) return null
  return {
    id,
    title: String(meta?.metadata?.title ?? doc.title ?? id),
    year: String(meta?.metadata?.year ?? doc.year ?? '').slice(0, 4),
    url: `https://archive.org/download/${encodeURIComponent(id)}/${file.name.split('/').map(encodeURIComponent).join('/')}`,
  }
}

function next(name) {
  // A film with no video file a Pi plays is skipped (a few tries).
  for (let i = 0; i < 4; i++) {
    const film = pickFilm(name)
    if (film) {
      current = film
      startedAt = Date.now()
      return
    }
  }
  throw new Error('No playable film found this time.')
}

function Message({ title, text, k }) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center bg-black text-white gap-[8px] px-[24px]">
      <span className={`text-[${Math.round(22 * k)}px] font-bold`}>{title}</span>
      <span className={`text-[${Math.round(15 * k)}px] text-white/70 text-center`}>{text}</span>
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.6, Math.min(width / 800, height / 480) * 1.15))
  const name = String(app.state.collection || 'feature_films')
  if (name !== collection) {
    collection = name
    current = null
  }
  if (problem && Date.now() - problemAt < RETRY_MS) {
    frameos.setNextSleep(Math.max(1, (RETRY_MS - (Date.now() - problemAt)) / 1000))
    return <Message k={k} title="Archive films" text={problem} />
  }
  const fit = app.state.fit === 'cover' ? 'cover' : 'contain'
  const play = () => frameos.video('film', { src: current.url, fit, fps: Number(app.state.fps) || 30 })
  let video = null
  try {
    if (!current) next(name)
    video = play()
    if (video.state === 'ended' || (video.state === 'error' && video.id !== 0)) {
      if (video.state === 'error') frameos.log(`Skipping ${current.id}: ${video.error}`)
      tries = video.state === 'error' ? tries + 1 : 0
      if (tries > 3) throw new Error(`Films do not play: ${video.error}`)
      const before = current.url
      next(name)
      if (current.url === before) frameos.releaseVideo(video)
      video = play()
    }
    problem = ''
  } catch (error) {
    problem = String(error?.message ?? error)
    problemAt = Date.now()
    frameos.setNextSleep(RETRY_MS / 1000)
    return <Message k={k} title="Archive films" text={problem} />
  }
  if (video.state === 'error') {
    const here = video.id === 0 && /cannot play it|, not here/.test(video.error || '')
    if (!here) {
      problem = video.error || 'The film did not play.'
      problemAt = Date.now()
      current = null
    }
    return <Message k={k} title={here ? 'Video does not play here' : 'Archive films'} text={video.error} />
  }
  const titled = app.state.titles !== false && Date.now() - startedAt < TITLE_MS
  if (titled) frameos.setNextSleep(Math.max(0.5, (TITLE_MS - (Date.now() - startedAt)) / 1000))
  return (
    <div className="relative w-full h-full bg-black" onClick={() => { current = null }}>
      <img className={`w-full h-full object-${fit}`} src={video} />
      {titled ? (
        <div className={`absolute left-[${Math.round(16 * k)}px] bottom-[${Math.round(14 * k)}px] flex flex-col px-[12px] py-[8px] rounded-[8px] bg-black/60 max-w-[80%]`}>
          <span className={`text-[${Math.round(18 * k)}px] font-bold text-white truncate`}>{current.title}</span>
          <span className={`text-[${Math.round(13 * k)}px] text-white/70`}>
            {[current.year, 'Internet Archive'].filter(Boolean).join(' · ')}
          </span>
        </div>
      ) : null}
    </div>
  )
}
